r = primitives.call(name='locate_vlabench_entity', entity_name='rose', prompt='rose flower on table')
print(r.ok)
out = r.output if r.ok else None
if out is not None and isinstance(out, dict):
    for k in out:
        v = out[k]
        s = str(v)
        print(k, ':', s[:300])
else:
    print(r)

h = 'vlabench:visual:2:rose:5'
r = primitives.call(name='grasp_vlabench_entity', entity_name='rose', evidence_handles=[h], prompt='grasp rose stem')
print('grasp ok', r.ok)
out = r.output if r.ok else r
if isinstance(out, dict):
    for k in out:
        s = str(out[k])
        print(k, ':', s[:250])
else:
    print(out)

r = primitives.call(name='observe_vlabench_scene', prompt='check grasp state')
print(r.ok)
if r.ok and isinstance(r.output, dict):
    o = r.output
    for k in o:
        if k in ('object_grounding_evidence',):
            g = o[k]
            if isinstance(g, dict):
                print('grasped', g.get('grasped_obj_name'))
                ev = g.get('entity_evidence', {})
                if isinstance(ev, dict):
                    for n in ev:
                        print(n, ev[n].get('xpos'))
        elif k not in ('visual_evidence', 'action_schema'):
            print(k, str(o[k])[:150])
